__hurt-part-name {\n  flex-shrink: 0;\n  max-width: 40%;\n  overflow-wrap: break-word;\n  font-size: var(--stb-font-size-xs);\n  color: var(--stb-color-text);\n}\n\n.stb-ov__hurt-part-limit {\n  flex: 1;\n  min-width: 0;\n  font-size: var(--stb-font-size-xs);\n  color: var(--stb-color-text-dim);\n}\n\n.stb-ov__hurt-badge {\n  flex-shrink: 0;\n  padding: 0 8px;\n  border-radius: 999px;\n  font-size: 10px;\n  line-height: 1.6;\n}\n"],"sourceRoot":""}]);
